cd /Users/shengyin/.codex/worktrees/scientific-sales-impact/Open-Trend-Tracker/backend && PYTHONPATH=. uv run python -c "
from app.analysis import chinese_pairs as cp
p,f,s,m=cp.load(); obs,_=cp.independent_observations(cp.pair_sales(p,s,m),f)
c=[o for o in obs if all(o[f'status_year_{k}']=='observed' for k in cp.YEARS)]
for lvl,t in [('feature','Parking assistance'),('subcategory','battery_range'),('category','Energy & Charging'),('subcategory','hybrid_powertrain')]:
  print(t)
  for o in c:
    if t in o['items'][lvl]: print('  ',o['car_model'],o['powertrain'],o['sales_series'],o['baseline_year'],o['baseline_sales'],[o[f'change_pct_year_{k}'] for k in cp.YEARS], 'ELIG' if o['publication_eligible'] else '')
"

