1	import { useEffect, useState, type CSSProperties } from "react";
2	import { useImpactForecast } from "../api/queries";
3	import type { ImpactCategory } from "../api/types";
4	import { errorMessage } from "../api/client";
5	import { StateMessage } from "../components/common/StateMessage";
6	import { Footer } from "../components/layout/Footer";
7	import { NavBar } from "../components/layout/NavBar";
8	import { TrackButton } from "../components/TrackButton";
9	import { config } from "../config";
10	import { featureClusters } from "../content/featureNews";
11	import { FeatureCard, type SavedProblemAnalysis } from "./FeatureTrendsPage";
12	import { legacyFeatureId } from "../state/trackedFeatures";
13	import { usePageTitle } from "./usePageTitle";
14	import styles from "./ImpactForecastPage.module.css";
15	
16	const CATEGORY_COLORS = ["#0066b1", "#7b61a8", "#dc7b22", "#087e8b", "#c24c63", "#39805d", "#88743c"];
17	const colorAt = (index: number) => CATEGORY_COLORS[index % CATEGORY_COLORS.length]!;
18	
19	type ImpactPoint = ImpactCategory["impact_by_year"][number];
20	
21	function lastPoint(points: ImpactPoint[]) {
22	  return points.at(-1)!;
23	}
24	
25	const signed = (value: number, digits = 1) => `${value >= 0 ? "+" : ""}${value.toFixed(digits)}%`;
26	const signedUnits = (value: number) => `${value >= 0 ? "+" : ""}${Math.round(value).toLocaleString()} vehicles`;
27	
28	/** Latest estimate of a series, or a note when it did not pass the identification gates. */
29	const latestText = (points: ImpactPoint[]) =>
30	  points.length
31	    ? `${signedUnits(lastPoint(points).incremental_units ?? 0)} per nameplate (${signed(lastPoint(points).impact_pct)}) in year ${lastPoint(points).year}`
32	    : "effect not independently identified";
33	
34	/** Value range of a plot. It always includes zero because effects can be negative. */
35	function valueRange(values: number[]) {
36	  if (!values.length) return { lo: -1, hi: 1 };
37	  const lo = Math.min(0, ...values);
38	  const hi = Math.max(0, ...values);
39	  return hi - lo < 1 ? { lo, hi: lo + 1 } : { lo, hi };
40	}
41	
42	function CategoryPlot({
43	  categories,
44	  selectedId,
45	  onSelect,
46	}: {
47	  categories: ImpactCategory[];
48	  selectedId: string;
49	  onSelect: (id: string) => void;
50	}) {
51	  const width = 520;
52	  const height = 360;
53	  const pad = { left: 54, right: 58, top: 24, bottom: 48 };
54	  const { lo, hi } = valueRange(
55	    categories.flatMap((category) => category.impact_by_year.map((point) => point.impact_pct)),
56	  );
57	  const x = (year: number) => pad.left + ((year - 1) / 3) * (width - pad.left - pad.right);
58	  const y = (value: number) => pad.top + ((hi - value) / (hi - lo)) * (height - pad.top - pad.bottom);
59	  const ticks = Array.from({ length: 5 }, (_, index) => lo + ((hi - lo) / 4) * index);
60	
61	  return (
62	    <svg
63	      className={styles.linePlot}
64	      viewBox={`0 0 ${width} ${height}`}
65	      role="group"
66	      aria-label="Category sales impact by year after launch. Select a category line to see its features."
67	    >
68	      {ticks.map((tick) => (
69	        <g key={tick}>
70	          <line x1={pad.left} x2={width - pad.right} y1={y(tick)} y2={y(tick)} className={styles.gridLine} />
71	          <text x={pad.left - 10} y={y(tick) + 4} textAnchor="end" className={styles.axisLabel}>
72	            {tick.toFixed(1)}%
73	          </text>
74	        </g>
75	      ))}
76	      <line x1={pad.left} x2={width - pad.right} y1={y(0)} y2={y(0)} className={styles.zeroLine} />
77	      {[1, 2, 3, 4].map((year) => (
78	        <text key={year} x={x(year)} y={height - 15} textAnchor="middle" className={styles.axisLabel}>
79	          Year {year}
80	        </text>
81	      ))}
82	      {categories.map((category, index) => {
83	        if (!category.impact_by_year.length) return null;
84	        const color = colorAt(index);
85	        const points = category.impact_by_year.map((point) => `${x(point.year)},${y(point.impact_pct)}`).join(" ");
86	        const selected = category.id === selectedId;
87	        const end = lastPoint(category.impact_by_year);
88	        return (
89	          <g
90	            key={category.id}
91	            className={`${styles.categoryLine} ${selectedId && !selected ? styles.categoryLineDimmed : ""}`}
92	            role="button"
93	            tabIndex={0}
94	            aria-pressed={selected}
95	            aria-label={`${category.label}: ${signed(end.impact_pct)} in year ${end.year}`}
96	            onClick={() => onSelect(category.id)}
97	            onKeyDown={(event) => {
98	              if (event.key === "Enter" || event.key === " ") {
99	                event.preventDefault();
100	                onSelect(category.id);
101	              }
102	            }}
103	          >
104	            <polyline points={points} className={styles.hitLine} />
105	            <polyline
106	              points={points}
107	              fill="none"
108	              stroke={color}
109	              strokeWidth={selected ? 4.5 : 3}
110	              strokeLinejoin="round"
111	              strokeLinecap="round"
112	            />
113	            {category.impact_by_year.map((point) => (
114	              <circle key={point.year} cx={x(point.year)} cy={y(point.impact_pct)} r={selected ? 5 : 4} fill={color} />
115	            ))}
116	            {selected && (
117	              <text x={x(end.year) + 10} y={y(end.impact_pct) + 4} className={styles.endLabel} fill={color}>
118	                {signed(end.impact_pct)}
119	              </text>
120	            )}
121	          </g>
122	        );
123	      })}
124	    </svg>
125	  );
126	}
127	
128	function ImpactChart({ points, lo, hi, color }: { points: ImpactPoint[]; lo: number; hi: number; color: string }) {
129	  const width = 360;
130	  const height = 112;
131	  const pad = { left: 34, right: 10, top: 8, bottom: 20 };
132	  const x = (year: number) => pad.left + ((year - 1) / 3) * (width - pad.left - pad.right);
133	  const y = (value: number) => pad.top + ((hi - value) / (hi - lo)) * (height - pad.top - pad.bottom);
134	  const line = points.map((point) => `${x(point.year)},${y(point.impact_pct)}`).join(" ");
135	  const band = [
136	    ...points.map((point) => `${x(point.year)},${y(point.upper_pct ?? point.impact_pct)}`),
137	    ...[...points].reverse().map((point) => `${x(point.year)},${y(point.lower_pct ?? point.impact_pct)}`),
138	  ].join(" ");
139	
140	  return (
141	    <svg className={styles.featurePlot} viewBox={`0 0 ${width} ${height}`} aria-hidden="true">
142	      {[lo, (lo + hi) / 2, hi].map((tick) => (
143	        <g key={tick}>
144	          <line x1={pad.left} x2={width - pad.right} y1={y(tick)} y2={y(tick)} className={styles.gridLine} />
145	          <text x={pad.left - 6} y={y(tick) + 3} textAnchor="end" className={styles.axisLabel}>
146	            {tick.toFixed(0)}%
147	          </text>
148	        </g>
149	      ))}
150	      <line x1={pad.left} x2={width - pad.right} y1={y(0)} y2={y(0)} className={styles.zeroLine} />
151	      {[1, 2, 3, 4].map((year) => (
152	        <text key={year} x={x(year)} y={height - 4} textAnchor="middle" className={styles.axisLabel}>
153	          Y{year}
154	        </text>
155	      ))}
156	      <polygon points={band} fill={color} fillOpacity={0.16} />
157	      <polyline points={line} fill="none" stroke={color} strokeWidth="2.5" strokeLinejoin="round" />
158	      {points.map((point) => (
159	        <circle key={point.year} cx={x(point.year)} cy={y(point.impact_pct)} r="3" fill={color} />
160	      ))}
161	    </svg>
162	  );
163	}
164	
165	function ImpactCard({
166	  title,
167	  meta,
168	  points,
169	  range,
170	  color,
171	  level,
172	  trackId,
173	}: {
174	  title: string;
175	  meta: string;
176	  points: ImpactPoint[];
177	  range: { lo: number; hi: number };
178	  color: string;
179	  level: "subcategory" | "feature";
180	  trackId?: string;
181	}) {
182	  const last = lastPoint(points);
183	  const missingYears = [1, 2, 3, 4].filter((year) => !points.some((point) => point.year === year));
184	  return (
185	    <article className={`${styles.featureCard} ${level === "subcategory" ? styles.subcategoryCard : ""}`}>
186	      <div className={styles.featureTop}>
187	        <div>
188	          <strong>{title}</strong>
189	          <span>{meta}</span>
190	        </div>
191	        <div className={styles.impactValue}>
192	          <b>{signedUnits(last.incremental_units ?? 0)}</b>
193	          <span>
194	            {signed(last.impact_pct, 1)} · Y{last.year}
195	            {last.lower_units !== undefined && last.upper_units !== undefined
196	              ? ` · 95% range ${last.lower_units.toLocaleString()} to ${last.upper_units.toLocaleString()}`
197	              : ""}
198	            {last.nameplates ? ` · ${last.nameplates} nameplates` : ""}
199	          </span>
200	        </div>
201	      </div>
202	      <ImpactChart points={points} lo={range.lo} hi={range.hi} color={color} />
203	      {missingYears.length > 0 && (
204	        <p className={styles.missingYears}>
205	          Y{missingYears.join(", Y")} unavailable: each year needs observed sales from at least five pairs in this group
206	          and five comparison pairs.
207	        </p>
208	      )}
209	      {trackId && <TrackButton id={trackId} label={title} />}
210	    </article>
211	  );
212	}
213	
214	function LegacyFeaturePanel({ category, color }: { category: ImpactCategory; color: string }) {
215	  const groups = category.subcategories.filter((sub) => sub.impact_by_year || sub.legacy_features.length);
216	  const series = groups.flatMap((sub) => [
217	    sub.impact_by_year ?? [],
218	    ...sub.legacy_features.map((feature) => feature.impact_by_year),
219	  ]);
220	  const range = valueRange(
221	    series.flat().flatMap((point) => [point.lower_pct ?? point.impact_pct, point.upper_pct ?? point.impact_pct]),
222	  );
223	  const plural = (n: number, word: string) => `${n} ${word}${n === 1 ? "" : "s"}`;
224	
225	  return (
226	    <section className={styles.panel} aria-labelledby="legacy-title">
227	      <div className={styles.panelHeading}>
228	        <span className={styles.step}>2</span>
229	        <div>
230	          <h2 id="legacy-title">Subcategories and features</h2>
231	          <p>Balanced independent panel · conditional event-study effect · band = clustered 95% interval</p>
232	        </div>
233	      </div>
234	      {groups.length ? (
235	        <div className={styles.featureList}>
236	          {groups.map((sub) => (
237	            <div key={sub.id}>
238	              {sub.impact_by_year ? (
239	                <ImpactCard
240	                  title={sub.label}
241	                  meta={`Subcategory · ${plural(sub.independent_nameplates, "independent nameplate")}`}
242	                  points={sub.impact_by_year}
243	                  range={range}
244	                  color={color}
245	                  level="subcategory"
246	                />
247	              ) : (
248	                <p className={styles.emptyEvidence}>
249	                  {sub.label}: {sub.identification_reason} (
250	                  {plural(sub.independent_nameplates, "independent nameplate")}).
251	                </p>
252	              )}
253	              {sub.legacy_features.map((feature) =>
254	                feature.impact_by_year.length ? (
255	                  <ImpactCard
256	                    key={feature.name}
257	                    title={feature.name}
258	                    meta={`Feature · ${plural(feature.independent_nameplates, "independent nameplate")}`}
259	                    points={feature.impact_by_year}
260	                    range={range}
261	                    color={color}
262	                    level="feature"
263	                    trackId={legacyFeatureId(category.id, feature.name)}
264	                  />
265	                ) : (
266	                  <div key={feature.name}>
267	                    <p className={styles.emptyEvidence}>
268	                      {feature.name}: {feature.identification_reason} (
269	                      {plural(feature.independent_nameplates, "independent nameplate")}).
270	                    </p>
271	                    <TrackButton id={legacyFeatureId(category.id, feature.name)} label={feature.name} />
272	                  </div>
273	                ),
274	              )}
275	            </div>
276	          ))}
277	        </div>
278	      ) : (
279	        <p className={styles.emptyEvidence}>
280	          No Chinese version pair in this category yet, so no feature-level sales effect is estimated.
281	        </p>
282	      )}
283	    </section>
284	  );
285	}
286	
287	function NewsFeaturePanel({ category, problems }: { category: ImpactCategory; problems: SavedProblemAnalysis | null }) {
288	  const ids = new Set(
289	    category.subcategories.flatMap((subcategory) => subcategory.news_features.map((feature) => feature.id)),
290	  );
291	  const features = featureClusters.filter((feature) => ids.has(feature.id));
292	
293	  return (
294	    <section className={styles.panel} aria-labelledby="news-title">
295	      <div className={styles.panelHeading}>
296	        <span className={styles.step}>3</span>
297	        <div>
298	          <h2 id="news-title">New features in the news</h2>
299	          <p>Market signal, not causal lift · sorted by priority</p>
300	        </div>
301	      </div>
302	      {features.length ? (
303	        <div className={styles.newsList}>
304	          {features.map((feature) => (
305	            <FeatureCard key={feature.id} feature={feature} analysis={problems} />
306	          ))}
307	        </div>
308	      ) : (
309	        <p className={styles.emptyEvidence}>No recent news feature is mapped to this category.</p>
310	      )}
311	    </section>
312	  );
313	}
314	
315	export function ImpactForecastPage() {
316	  usePageTitle("Sales Impact Forecast");
317	  const forecast = useImpactForecast();
318	  const [selectedId, setSelectedId] = useState("");
319	  const [problems, setProblems] = useState<SavedProblemAnalysis | null>(null);
320	  useEffect(() => {
321	    fetch(`${config.apiBaseUrl}/agent/problems`)
322	      .then((response) => (response.ok ? response.json() : null))
323	      .then(setProblems)
324	      .catch(() => setProblems(null));
325	  }, []);
326	  const categories = forecast.data?.categories ?? [];
327	  const selected = categories.find((category) => category.id === selectedId) ?? categories[0];
328	  const activeId = selected?.id ?? "";
329	  const selectedIndex = categories.findIndex((category) => category.id === activeId);
330	  const selectedColor = colorAt(Math.max(selectedIndex, 0));
331	
332	  return (
333	    <>
334	      <NavBar mockMode={config.useMocks} />
335	      <main className={styles.page}>
336	        <header className={styles.hero}>
337	          <div>
338	            <p className={styles.eyebrow}>Portfolio planning · Sales change, years 1–4 after launch</p>
339	            <h1>Sales Impact Forecast</h1>
340	            <p className={styles.lead}>
341	              Estimates appear only when independent nameplates separate a feature from market movement and its launch
342	              bundle. Unidentified effects stay unavailable instead of becoming an unsupported sales claim.
343	            </p>
344	          </div>
345	          {forecast.data && (
346	            <div className={styles.stats} aria-label="Forecast data coverage">
347	              <div>
348	                <b>{forecast.data.categories.length}</b>
349	                <span>categories</span>
350	              </div>
351	              <div>
352	                <b>
353	                  {forecast.data.complete_nameplate_count}/{forecast.data.independent_nameplate_count}
354	                </b>
355	                <span>complete / independent nameplates</span>
356	              </div>
357	              <div>
358	                <b>{forecast.data.isolated_feature_count}</b>
359	                <span>identified features</span>
360	              </div>
361	              <div>
362	                <b>{forecast.data.news_feature_count}</b>
363	                <span>news signals</span>
364	              </div>
365	            </div>
366	          )}
367	        </header>
368	
369	        {forecast.isLoading && <StateMessage title="Loading sales-impact estimates…" />}
370	        {forecast.isError && (
371	          <StateMessage
372	            tone="error"
373	            title="Forecast unavailable"
